n, mod = read_ints()

edge_sum = n * (n - 1) // 2
dp = [[[0] * (n + 1) for _ in range(edge_sum + 1)] for _ in range(n + 1)]
dp[1][0][1] = 1

for i in range(1, n):
    for j in range(edge_sum + 1):
        for k in range(n + 1):
            val = dp[i][j][k]
            if val == 0:
                continue
            dp[i + 1][j + i][i + 1] = (dp[i + 1][j + i][i + 1] + val) % mod
            for l in range(i):
                dp[i + 1][j + i - 1 - l][k] = (dp[i + 1][j + i - 1 - l][k] + val) % mod

prefix_sum = [[[0] * (edge_sum + 1) for _ in range(n + 1)] for _ in range(n + 1)]
for i in range(n + 1):
    for k in range(n + 1):
        total = 0
        for j in range(edge_sum + 1):
            total += dp[i][j][k]
            total %= mod
            prefix_sum[i][k][j] = total

cumulative = [[[0] * (n + 1) for _ in range(edge_sum + 1)] for _ in range(n + 1)]
for i in range(n + 1):
    for j in range(edge_sum + 1):
        total = 0
        for k in range(n + 1):
            total += prefix_sum[i][k][j]
            total %= mod
            cumulative[i][j][k] = total

answers = [0] * (n + 1)
for i in range(1, n + 1):
    answer = i * answers[i - 1] % mod
    for k in range(n + 1):
        for j in range(1, edge_sum + 1):
            if dp[i][j][k] == 0:
                continue
            answer += dp[i][j][k] * (cumulative[i][j - 1][-1] - cumulative[i][j - 1][k])
            answer %= mod
    answers[i] = answer

print(answers[-1])
